const tejasServices=[{name:"Mumbai CSMT - Karmali Tejas Express",origin:"Mumbai CSMT",destination:"Karmali (Goa)",majorStations:["Dadar","Thane","Panvel","Ratnagiri","Kudal"],description:"The first ever Tejas Express, connecting Mumbai to the popular tourist destination of Goa."},{name:"New Delhi - Chandigarh Tejas Express",origin:"New Delhi",destination:"Chandigarh",majorStations:["Ambala Cantonment"],description:"A fast and luxurious connection between the National Capital and Chandigarh."},{name:"Lucknow - New Delhi Tejas Express",origin:"Lucknow NE",destination:"New Delhi",majorStations:["Kanpur Central","Ghaziabad"],description:"The first train in India fully operated by IRCTC, offering premium services to passengers."},{name:"Ahmedabad - Mumbai Central Tejas Express",origin:"Ahmedabad",destination:"Mumbai Central",majorStations:["Nadiad","Vadodara","Bharuch","Surat","Vapi","Borivali"],description:"The second IRCTC-operated train, connecting two major business hubs in Western India."}],routes=[{origin:"Mumbai CSMT",destination:"Karmali",importantStations:["Panvel","Ratnagiri"],regions:["Maharashtra","Goa"]},{origin:"New Delhi",destination:"Chandigarh",importantStations:["Ambala Cantt"],regions:["Delhi","Haryana","Chandigarh"]},{origin:"Lucknow NE",destination:"New Delhi",importantStations:["Kanpur Central","Ghaziabad"],regions:["Uttar Pradesh","Delhi"]},{origin:"Ahmedabad",destination:"Mumbai Central",importantStations:["Vadodara","Surat"],regions:["Gujarat","Maharashtra"]}];function renderServices(){const a=document.getElementById("services-container");a&&(a.innerHTML=tejasServices.map(a=>`\n    <div class="card">\n      <i class="fa-solid fa-train icon-feature"></i>\n      <h3>${a.name}</h3>\n      <p style="margin-bottom: 10px;"><strong>${a.origin} <i class="fa-solid fa-arrow-right"></i> ${a.destination}</strong></p>\n      <p style="font-size: 0.9rem; color: #ccc;"><strong>Major Stations:</strong> ${a.majorStations.join(", ")}</p>\n      <p style="margin-top: 10px;">${a.description}</p>\n    </div>\n  `).join(""))}function renderRoutes(){const a=document.getElementById("routes-container");a&&(a.innerHTML=routes.map(a=>`\n    <div class="route-card">\n      <div>\n        <div class="origin-dest">${a.origin} <i class="fa-solid fa-arrow-right" style="color: var(--tejas-yellow); margin: 0 10px;"></i> ${a.destination}</div>\n        <div class="stations"><strong>Via:</strong> ${a.importantStations.join(", ")}</div>\n      </div>\n      <div>\n        <span style="background: var(--tejas-orange); color: #fff; padding: 5px 10px; border-radius: 4px; font-size: 0.8rem; font-weight: bold;">\n          ${a.regions.join(" &middot; ")}\n        </span>\n      </div>\n    </div>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderServices(),renderRoutes()});